"use strict";

const assert = require("node:assert/strict");
const path = require("node:path");
const test = require("node:test");

const { loadConfig } = require("../src/config.js");
const { runCommand } = require("../src/modes/command.js");
const { createFakeGitHub } = require("./helpers/fake-github.js");

const repositoryRoot = path.resolve(__dirname, "../../../..");
const HEAD = "6".repeat(40);
const BOT_AUTHORS = ["dependabot[bot]", "renovate[bot]"];
const UNSAFE_AUTHORS = ["dependabot\u200b[bot]", "bad--login[bot]", "[bot]", "alice\n"];

function commandState(author) {
  return {
    pullRequest: {
      number: 42,
      nodeId: "PR_kwDOABC42",
      title: "chore(deps): bump yaml",
      body: "",
      draft: false,
      author,
      headOid: HEAD,
      state: "open",
      baseBranch: "main",
      baseRepository: { owner: "nvidia", repo: "k8s-test-infra" },
    },
    files: [{ path: "go.mod", additions: 1, deletions: 1, status: "modified" }],
    labels: [],
    issueComments: [
      { id: 9001, issueNumber: 42, body: "/lgtm", author: "alice", authorType: "User", edited: false },
      { id: 9002, issueNumber: 42, body: "/hold", author: "carol", authorType: "User", edited: false },
    ],
    collaboratorAccess: {
      alice: { liveCollaborator: false, permission: "read" },
      carol: { liveCollaborator: true, permission: "write" },
    },
    defaultBranchRevision: "7".repeat(40),
    contents: {
      "/OWNERS": "reviewers: [alice]\napprovers: [bob]\n",
      "/OWNERS_ALIASES": "aliases: {}\n",
    },
    comments: [],
  };
}

function command(github, commentId) {
  return runCommand({
    event: {
      action: "created",
      repository: {
        owner: { login: "NVIDIA" },
        name: "k8s-test-infra",
        full_name: "NVIDIA/k8s-test-infra",
      },
      issue: { number: 42, pull_request: { url: "event-url" } },
      comment: { id: commentId },
    },
    github,
    config: loadConfig(repositoryRoot),
    dryRun: false,
    now: () => "2026-09-17T12:00:00.000Z",
  });
}

test("pull request author context accepts human and app bot logins only", () => {
  const { validAuthorContext } = require("../src/pull-request-author.js");
  for (const login of ["alice", "Pr-Author", "a".repeat(39), ...BOT_AUTHORS, "Dependabot[bot]"]) {
    assert.equal(validAuthorContext(login), true, login);
  }
  for (const login of [...UNSAFE_AUTHORS, "", "-alice", "alice-", "a".repeat(40),
    "dependabot[bot][bot]", "dependabot[BOT]", null, 42]) {
    assert.equal(validAuthorContext(login), false, String(login));
  }
});

for (const author of BOT_AUTHORS) {
  test(`reviewer and hold commands apply on a pull request authored by ${author}`, async () => {
    const github = createFakeGitHub(commandState(author));

    const lgtm = await command(github, 9001);
    const hold = await command(github, 9002);

    assert.equal(lgtm.status, "complete");
    assert.deepEqual(lgtm.commands.map(({ name, status }) => [name, status]), [["lgtm", "applied"]]);
    assert.equal(hold.status, "complete");
    assert.deepEqual(hold.commands.map(({ name, status }) => [name, status]), [["hold", "applied"]]);
    assert.deepEqual(github.snapshot().map(({ name }) => name).sort(), [
      "do-not-merge/hold", "do-not-merge/needs-approval", "lgtm",
    ]);
  });
}

for (const author of UNSAFE_AUTHORS) {
  test(`commands reject the unsafe author ${JSON.stringify(author)}`, async () => {
    const github = createFakeGitHub(commandState(author));
    await assert.rejects(() => command(github, 9001), {
      message: "live pull request state or base repository is invalid",
    });
    assert.deepEqual(github.calls.addPolicyLabel, []);
  });
}

"use strict";

const assert = require("node:assert/strict");
const test = require("node:test");

const { authorizeCommand } = require("../src/commands/authorization.js");

function command(name) {
  return { name, line: 1, raw: `/${name}` };
}

function actor(login = "reviewer", overrides = {}) {
  return {
    resolved: true,
    deleted: false,
    login,
    type: "User",
    liveCollaborator: false,
    permission: "read",
    ...overrides,
  };
}

function context(overrides = {}) {
  return {
    actor: actor(),
    author: "author",
    reviewers: ["reviewer", "owner"],
    approvers: ["approver", "owner"],
    owners: ["reviewer", "approver", "owner"],
    ...overrides,
  };
}

test("authorizes current human reviewers and approvers for evidence", () => {
  assert.deepEqual(authorizeCommand(command("lgtm"), context()), {
    allowed: true,
    reason: "authorized",
    actor: "reviewer",
    actorRole: "reviewer",
  });
  assert.deepEqual(authorizeCommand(command("approve"), context({
    actor: actor("approver"),
  })), {
    allowed: true,
    reason: "authorized",
    actor: "approver",
    actorRole: "approver",
  });
  assert.equal(authorizeCommand(command("approve"), context()).allowed, false);
});

test("never accepts PR-author or bot evidence", () => {
  assert.equal(authorizeCommand(command("lgtm"), context({
    actor: actor("author"),
    reviewers: ["author"],
  })).reason, "author-cannot-provide-evidence");
  assert.equal(authorizeCommand(command("approve"), context({
    actor: actor("dependabot", { type: "Bot", permission: "write", liveCollaborator: true }),
    approvers: ["dependabot"],
  })).reason, "actor-not-human");
});

test("authorizes holds only for current owners or write collaborators", () => {
  for (const name of ["hold", "unhold"]) {
    assert.equal(authorizeCommand(command(name), context()).allowed, true);
    assert.equal(authorizeCommand(command(name), context({
      actor: actor("maintainer", { liveCollaborator: true, permission: "write" }),
    })).allowed, true);
    assert.equal(authorizeCommand(command(name), context({
      actor: actor("reader"),
    })).allowed, false);
  }
});

test("authorizes /retest for the author, owners, or write collaborators", () => {
  const value = command("retest");
  assert.equal(authorizeCommand(value, context({ actor: actor("author") })).allowed, true);
  assert.equal(authorizeCommand(value, context()).allowed, true);
  assert.equal(authorizeCommand(value, context({
    actor: actor("maintainer", { liveCollaborator: true, permission: "maintain" }),
  })).allowed, true);
  assert.equal(authorizeCommand(value, context({ actor: actor("reader") })).allowed, false);
});

test("fails closed for stale, deleted, malformed, and unknown identities", () => {
  const invalidActors = [
    null,
    {},
    actor("reviewer", { resolved: false }),
    actor("reviewer", { error: true }),
    actor("reviewer", { deleted: true }),
    actor("bad_login!"),
    actor("reviewer", { permission: "unknown" }),
  ];
  for (const value of invalidActors) {
    assert.equal(authorizeCommand(command("lgtm"), context({ actor: value })).allowed, false);
  }
});

test("accepts app bot pull request authors and rejects unsafe author context", () => {
  assert.deepEqual(authorizeCommand(command("lgtm"), context({ author: "dependabot[bot]" })), {
    allowed: true,
    reason: "authorized",
    actor: "reviewer",
    actorRole: "reviewer",
  });
  for (const author of ["alice​", "alice\n", "[bot]", "bad--login", "dependabot[bot][bot]", 42, null]) {
    assert.equal(authorizeCommand(command("lgtm"), context({ author })).reason, "invalid-context", String(author));
  }
});

test("rejects unapproved command shapes and invalid authority context", () => {
  const invalidCommands = [
    null,
    {},
    command("help"),
    command("backport"),
    command("cherry-pick"),
    { ...command("lgtm"), targetBranch: null },
    { ...command("lgtm"), extra: true },
  ];
  for (const value of invalidCommands) {
    assert.equal(authorizeCommand(value, context()).reason, "invalid-command");
  }
  assert.equal(authorizeCommand(command("lgtm"), context({ reviewers: "reviewer" })).reason, "invalid-context");
});

