package cri

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
	"go.uber.org/zap"
	"go.uber.org/zap/zapcore"
	"go.uber.org/zap/zaptest/observer"

	"github.com/NVIDIA/k8s-test-infra/internal/agent/host"
	"github.com/NVIDIA/k8s-test-infra/internal/cri"
)

// stubRuntime is a Runtime whose Installed, Setup and Cleanup return what the
// test says, counting the calls to the last two.
type stubRuntime struct {
	missing              error
	setupErr, cleanupErr error
	setups, cleanups     int
}

func (s *stubRuntime) Installed() error { return s.missing }

func (s *stubRuntime) Setup(context.Context) error {
	s.setups++

	return s.setupErr
}

func (s *stubRuntime) Cleanup(context.Context) error {
	s.cleanups++

	return s.cleanupErr
}

// setupRig is a node with the toolkit binaries in the image and a cri
// simulator set up to install them. It captures the global logger, which
// rules out t.Parallel.
type setupRig struct {
	t    *testing.T
	h    *host.Host
	rt   *stubRuntime
	sim  *Simulator
	logs *observer.ObservedLogs
}

// toolkitBinaries are the binaries the image ships.
var toolkitBinaries = []string{"nvidia-container-runtime", "nvidia-ctk", "nvidia-cdi-hook"}

func newSetupRig(t *testing.T) *setupRig {
	t.Helper()

	source := t.TempDir()
	for _, b := range toolkitBinaries {
		require.NoError(t, os.WriteFile(filepath.Join(source, b), []byte("#!/bin/sh\n# "+b+"\n"), 0o755))
	}

	core, logs := observer.New(zapcore.DebugLevel)
	t.Cleanup(zap.ReplaceGlobals(zap.New(core)))

	r := &setupRig{t: t, h: host.New(t.TempDir()), rt: &stubRuntime{}, logs: logs}
	r.sim = New(r.h, Options{Runtime: r.rt, ToolkitSource: source})

	return r
}

func (r *setupRig) apply() error {
	r.t.Helper()

	require.NoError(r.t, r.sim.Stage(r.t.Context(), testState()))

	return r.sim.Apply(r.t.Context(), testState())
}

// logged reports whether a line at level mentions s, in its message or a
// field.
func (r *setupRig) logged(level zapcore.Level, s string) bool {
	for _, e := range r.logs.FilterLevelExact(level).All() {
		if strings.Contains(e.Message, s) {
			return true
		}

		for _, v := range e.ContextMap() {
			if strings.Contains(fmt.Sprint(v), s) {
				return true
			}
		}
	}

	return false
}

func (r *setupRig) exists(path string) bool {
	_, err := os.Lstat(r.h.HostPath(path))

	return err == nil
}

func (r *setupRig) link(path string) string {
	r.t.Helper()

	target, err := os.Readlink(r.h.HostPath(path))
	require.NoError(r.t, err)

	return target
}

func TestApplySetsUpTheRuntime(t *testing.T) {
	r := newSetupRig(t)

	require.NoError(t, r.apply())

	require.True(t, r.exists("/usr/bin/nvidia-cdi-hook"), "the hook the specs call is installed first")
	require.FileExists(t, r.h.RunPath(nvidiaSpecFile))
	require.Equal(t, 1, r.rt.setups)
	require.True(t, r.sim.Ready())
	require.True(t, r.logged(zapcore.InfoLevel, "container runtime set up"))
	require.Empty(t, r.logs.Filter(func(e observer.LoggedEntry) bool { return e.Level >= zapcore.WarnLevel }).All(),
		"a setup that works has nothing to warn about")
}

func TestApplyLeavesAForeignToolkitAlone(t *testing.T) {
	r := newSetupRig(t)
	require.NoError(t, os.MkdirAll(r.h.HostPath("/usr/bin"), 0o755))
	require.NoError(t, os.WriteFile(r.h.HostPath("/usr/bin/nvidia-container-runtime"), []byte("apt"), 0o755))

	require.NoError(t, r.apply())

	require.False(t, r.exists("/usr/bin/nvidia-cdi-hook"), "nothing is installed")
	require.Zero(t, r.rt.setups, "containerd is left alone")
	require.FileExists(t, r.h.RunPath(nvidiaSpecFile), "the specs are still published")
	require.True(t, r.sim.Ready())
	require.True(t, r.logged(zapcore.WarnLevel, "/usr/bin/nvidia-container-runtime"), "the log names what another installer owns")
}

func TestApplyLeavesANodeWithoutTheRuntimeAlone(t *testing.T) {
	r := newSetupRig(t)
	r.rt.missing = errors.New("containerd not found on the host's PATH")

	require.NoError(t, r.apply())

	require.False(t, r.exists("/usr/bin/nvidia-cdi-hook"), "nothing is installed")
	require.Zero(t, r.rt.setups)
	require.FileExists(t, r.h.RunPath(nvidiaSpecFile), "the specs are still published")
	require.True(t, r.sim.Ready(), "a CRI-O or k3s node is not a failure")
	require.True(t, r.logged(zapcore.WarnLevel, "containerd not found"), "the warning says what is missing")

	require.NoError(t, r.sim.Revoke(t.Context()))
	require.Zero(t, r.rt.cleanups, "nothing to revert")
}

func TestApplyReportsTheRuntimeSetup(t *testing.T) {
	for name, c := range map[string]struct {
		err   error
		ready bool
		// level and log are the line that says why; none when set up.
		level zapcore.Level
		log   string
	}{
		"set up":          {ready: true},
		"restart pending": {err: cri.ErrRestartPending, ready: true, level: zapcore.WarnLevel, log: "when the runtime restarts"},
		"failed":          {err: errors.New("containerd does not come back"), ready: false, level: zapcore.ErrorLevel, log: "containerd does not come back"},
	} {
		t.Run(name, func(t *testing.T) {
			r := newSetupRig(t)
			r.rt.setupErr = c.err

			require.NoError(t, r.apply(), "a failed setup does not fail the Apply wave")

			require.Equal(t, c.ready, r.sim.Ready())
			require.FileExists(t, r.h.RunPath(nvidiaSpecFile))

			if c.log != "" {
				require.True(t, r.logged(c.level, c.log), "the log says why")
			}
		})
	}
}

func TestApplyWithoutTheBinaries(t *testing.T) {
	r := newSetupRig(t)
	require.NoError(t, os.Remove(filepath.Join(r.sim.opts.ToolkitSource, "nvidia-ctk")))

	require.NoError(t, r.apply())

	require.Zero(t, r.rt.setups, "a handler whose runtime is missing is not registered")
	require.FileExists(t, r.h.RunPath(nvidiaSpecFile))
	require.False(t, r.sim.Ready())
	require.True(t, r.logged(zapcore.ErrorLevel, "nvidia-ctk"), "the log names the missing binary")
}

func TestRevokeRevertsTheRuntime(t *testing.T) {
	r := newSetupRig(t)
	require.NoError(t, r.apply())

	require.NoError(t, r.sim.Revoke(t.Context()))

	require.Equal(t, 1, r.rt.cleanups)
	_, err := os.Stat(r.h.RunPath(nvidiaSpecFile))
	require.ErrorIs(t, err, os.ErrNotExist)
	require.FileExists(t, r.h.HostPath(r.link("/usr/bin/nvidia-container-runtime")),
		"containers created through the handler keep calling the runtime")
}

func TestRevokeReportsACleanupFailure(t *testing.T) {
	r := newSetupRig(t)
	require.NoError(t, r.apply())
	r.rt.cleanupErr = errors.New("containerd does not come back")

	err := r.sim.Revoke(t.Context())

	require.ErrorContains(t, err, "containerd does not come back")
	_, statErr := os.Stat(r.h.RunPath(nvidiaSpecFile))
	require.ErrorIs(t, statErr, os.ErrNotExist, "the specs are withdrawn regardless")
}

func TestRevokeLeavesAForeignToolkitAlone(t *testing.T) {
	r := newSetupRig(t)
	require.NoError(t, os.MkdirAll(r.h.HostPath("/usr/bin"), 0o755))
	require.NoError(t, os.WriteFile(r.h.HostPath("/usr/bin/nvidia-ctk"), []byte("apt"), 0o755))
	require.NoError(t, r.apply())

	require.NoError(t, r.sim.Revoke(t.Context()))

	require.Zero(t, r.rt.cleanups)
}

"use strict";

const assert = require("node:assert/strict");
const test = require("node:test");

const { planLabelChanges } = require("../src/label-reconciliation.js");

function label(name, color = "123abc", description = `${name} description`) {
  return { name, color, description };
}

test("plans a create for each missing declared label", () => {
  const declared = [label("kind/test")];

  assert.deepEqual(planLabelChanges(declared, []), {
    creates: declared,
    updates: [],
    unchanged: [],
    unmanaged: [],
  });
});

test("plans an update when declared metadata differs", async (t) => {
  await t.test("color differs", () => {
    const declared = [label("kind/bug", "abcdef")];
    const existing = [label("kind/bug", "123456")];

    assert.deepEqual(planLabelChanges(declared, existing).updates, declared);
  });

  await t.test("description differs", () => {
    const declared = [label("kind/bug", "abcdef", "Declared description")];
    const existing = [label("kind/bug", "abcdef", "Existing description")];

    assert.deepEqual(planLabelChanges(declared, existing).updates, declared);
  });
});

test("compares names case-insensitively while preserving declared spelling", () => {
  const declared = [label("Kind/Bug")];
  const existing = [label("kind/bug", "123abc", declared[0].description)];

  assert.deepEqual(planLabelChanges(declared, existing), {
    creates: [],
    updates: [],
    unchanged: declared,
    unmanaged: [],
  });
});

test("plans no operation for an exact match", () => {
  const declared = [label("kind/bug")];

  assert.deepEqual(planLabelChanges(declared, declared), {
    creates: [],
    updates: [],
    unchanged: declared,
    unmanaged: [],
  });
});

test("classifies unmanaged existing labels without planning deletion", () => {
  const existing = [label("legacy/keep")];
  const plan = planLabelChanges([], existing);

  assert.deepEqual(plan, {
    creates: [],
    updates: [],
    unchanged: [],
    unmanaged: existing,
  });
  assert.equal(Object.hasOwn(plan, "deletes"), false);
});

test("sorts every plan category by lowercase label name", () => {
  const declared = [
    label("Zulu"),
    label("echo"),
    label("alpha", "abcdef"),
    label("Golf"),
    label("Bravo"),
    label("foxtrot", "abcdef"),
  ];
  const existing = [
    label("zulu", "123abc", declared[0].description),
    label("ALPHA", "123456"),
    label("omega"),
    label("golf", "123abc", declared[3].description),
    label("Delta"),
    label("Foxtrot", "123456", declared[5].description),
    label("charlie"),
  ];

  const plan = planLabelChanges(declared, existing);

  assert.deepEqual(plan.creates.map(({ name }) => name), ["Bravo", "echo"]);
  assert.deepEqual(plan.updates.map(({ name }) => name), ["alpha", "foxtrot"]);
  assert.deepEqual(plan.unchanged.map(({ name }) => name), ["Golf", "Zulu"]);
  assert.deepEqual(plan.unmanaged.map(({ name }) => name), ["charlie", "Delta", "omega"]);
});

test("fails closed when existing label names are duplicated case-insensitively", () => {
  const existing = [label("kind/bug"), label("Kind/Bug")];

  assert.throws(
    () => planLabelChanges([], existing),
    /duplicate existing label name: Kind\/Bug/i,
  );
});

test("fails closed when declared labels are invalid", async (t) => {
  const invalidCases = [
    ["not an array", null],
    ["not an object", [null]],
    ["blank name", [label("  ")]],
    ["invalid color", [label("kind/bug", "ABCDEF")]],
    ["blank description", [label("kind/bug", "abcdef", "  ")]],
    ["duplicate name", [label("kind/bug"), label("Kind/Bug")]],
  ];

  for (const [name, declared] of invalidCases) {
    await t.test(name, () => {
      assert.throws(() => planLabelChanges(declared, []), /invalid declared labels/i);
    });
  }
});

"use strict";

const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const test = require("node:test");
const { minimatch } = require("minimatch");
const YAML = require("yaml");
const { loadConfig } = require("../src/config.js");
const { evaluateCI } = require("../src/merge-ci.js");
const { MAX_API_COLLECTION_ITEMS, MAX_CHANGED_FILES } = require("../src/limits.js");
const { goldenCases, resultCode } = require("./helpers/merge-ci-golden.js");
const golden = require("./fixtures/merge-ci/golden-809294d.json");

const HEAD = "a".repeat(40);
const OLD_HEAD = "b".repeat(40);
const REPOSITORY = "nvidia/k8s-test-infra";
const WORKFLOWS = ["basic-checks.yaml", "validate-changelog.yaml", "automation-ci.yml", "helm.yaml", "dependency-integrity.yaml", "deploy-pages.yaml"];
const requiredCI = loadConfig(path.resolve(__dirname, "../../../..")).policy.merge.requiredCI;

function run(workflow, overrides = {}) {
  return {
    id: WORKFLOWS.indexOf(workflow) + 1,
    headOid: HEAD, repository: REPOSITORY, prNumber: 42, event: "pull_request",
    workflowPath: `.github/workflows/${workflow}`, workflowSourceRef: "refs/pull/42/merge",
    runNumber: 10, runAttempt: 1, status: "completed", conclusion: "success",
    ...overrides,
  };
}

function dco(overrides = {}) {
  return { id: 100, name: "DCO", appId: 1861, headOid: HEAD, status: "completed", conclusion: "success", ...overrides };
}

function evidence(overrides = {}) {
  return {
    repository: REPOSITORY, prNumber: 42, headOid: HEAD, baseBranch: "main",
    files: [{ path: "pkg/code.go" }],
    runs: [run("basic-checks.yaml"), run("validate-changelog.yaml")], checks: [dco()], requiredCI,
    ...overrides,
  };
}

function unmappedEvidence(overrides = {}) {
  const source = { headRepository: "contributor/k8s-test-infra", headBranch: "topic/readiness" };
  return evidence({
    ...source,
    runs: ["basic-checks.yaml", "validate-changelog.yaml"].map((workflow) => run(workflow, {
      ...source, prNumber: null, workflowSourceRef: undefined,
    })),
    ...overrides,
  });
}

test("policy requiredCI reproduces the 809294d hard-coded requirements for every golden case", () => {
  const cases = goldenCases();
  assert.deepEqual(cases.map(({ key }) => key), Object.keys(golden));
  for (const { key, inputs } of cases) {
    const actual = inputs.map((input) => resultCode(evaluateCI, { ...input, requiredCI })).join("");
    assert.equal(actual, golden[key], key);
  }
});

test("required workflows and checks come from the policy, not a built-in list", () => {
  const basic = { path: ".github/workflows/basic-checks.yaml" };
  const changelog = { path: ".github/workflows/validate-changelog.yaml" };
  const dcoCheck = { name: "DCO", appId: 1861 };
  assert.equal(evaluateCI(evidence({
    runs: [run("basic-checks.yaml")], requiredCI: { workflows: [basic], checks: [dcoCheck] },
  })), "SUCCESS");
  assert.equal(evaluateCI(evidence({
    requiredCI: { workflows: [basic, changelog, { path: ".github/workflows/ci.yaml" }], checks: [dcoCheck] },
  })), "PENDING");
  assert.equal(evaluateCI(evidence({
    runs: [run("validate-changelog.yaml")],
    requiredCI: { workflows: [{ ...basic, files: ["docs/**"] }, changelog], checks: [dcoCheck] },
  })), "SUCCESS");
  const withCla = { workflows: [basic, changelog], checks: [dcoCheck, { name: "license/cla", appId: 9 }] };
  assert.equal(evaluateCI(evidence({ requiredCI: withCla })), "PENDING");
  assert.equal(evaluateCI(evidence({
    requiredCI: withCla, checks: [dco(), dco({ id: 101, name: "license/cla", appId: 9 })],
  })), "SUCCESS");
  assert.equal(evaluateCI(evidence({
    requiredCI: withCla, checks: [dco(), dco({ id: 101, name: "license/cla", appId: 9, conclusion: "failure" })],
  })), "FAILED");
});

