		require.NoError(t, sim.Discard(t.Context()))

		after, err := os.Stat(path)
		require.NoError(t, err, "%s must outlive the teardown", rel)
		require.True(t, os.SameFile(before, after), "%s was replaced rather than emptied", rel)
	}
}

